"""The pins list (`pins/pins.json`) as the server's and the CLI's Python enums, caps and ref key
builder, and the dashboard's TypeScript twin."""

from __future__ import annotations

import json
import textwrap

from ..pins import Pins, PinTerm
from ..probe_contracts import Contracts
from .typescript import member_key

SOURCE = "contracts/probe_contracts/pins/pins.json"
WIDTH = 100

_PY_HEADER = (
    f"# GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "# Do not edit: change the list there and rerun.\n"
)
_TS_HEADER = (
    f"// GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "// Do not edit: change the list there and rerun.\n"
)

#: (class name, the list's field, the class doc), in the order every target writes them.
_ENUMS = (
    ("PinKind", "kinds", "What a pin shows: one view kind, the `kind` of its ref."),
    ("PinAnchorKind", "anchor_kinds", "Where a view lives: the project or one of its experiments."),
    ("PinMetricKind", "metric_kinds", "The metric kinds Probe names; a chart pin takes any kind a run logs."),
    ("PinErrorCode", "error_codes", "A refused pin call's `detail.code`."),
)

#: The server runs 3.12: the stdlib StrEnum.
_SERVER_PRELUDE = "from enum import StrEnum\n"
#: The CLI runs on 3.10 too: 3.11's StrEnum spelled by hand.
_AGENT_PRELUDE = '''from enum import Enum


class StrEnum(str, Enum):
    """3.11's StrEnum on 3.10 too: `str(member)` is its value."""

    def __str__(self) -> str:
        return str(self.value)
'''

_BUILD_REF_KEY = '''

def build_ref_key(ref: Mapping[str, object]) -> str:
    """A pin's identity: `<kind>:` plus the ref's canonical JSON (sorted keys, no spaces, non-ASCII
    as is), the same string the dashboard builds (`ref_key_vectors.json`)."""
    return f"{ref['kind']}:" + json.dumps(ref, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
'''


def _wrap(text: str, prefix: str) -> str:
    lines = textwrap.wrap(text, WIDTH - len(prefix), break_long_words=False, break_on_hyphens=False)
    return "".join(f"{prefix}{line}\n" for line in lines)


def _load(contracts: Contracts) -> Pins:
    return contracts.pins or Pins.load()


def _render_python_enum(name: str, doc: str, members: tuple[PinTerm, ...]) -> str:
    body = "".join(_wrap(m.doc, "    #: ") + f"    {m.name.upper()} = {json.dumps(m.name)}\n" for m in members)
    return f"\n\nclass {name}(StrEnum):\n    \"\"\"{doc}\"\"\"\n\n{body}"


def _render_python(contracts: Contracts, prelude: str) -> str:
    pins = _load(contracts)
    enums = "".join(_render_python_enum(name, doc, getattr(pins, field)) for name, field, doc in _ENUMS)
    caps = "".join(_wrap(c.doc, "#: ") + f"{c.name.upper()} = {c.value}\n" for c in pins.caps)
    names = sorted([*(name for name, _, _ in _ENUMS), *(c.name.upper() for c in pins.caps), "build_ref_key"])
    exports = "".join(f'    "{name}",\n' for name in names)
    return (
        _PY_HEADER
        + f'"""{textwrap.fill(pins.doc, WIDTH - 4, break_long_words=False)}\n"""\n\n'
        + "from __future__ import annotations\n\nimport json\nfrom collections.abc import Mapping\n"
        + prelude
        + f"\n__all__ = [\n{exports}]\n"
        + enums
        + "\n\n"
        + caps
        + _BUILD_REF_KEY
    )


def render_pins_server(contracts: Contracts) -> str:
    return _render_python(contracts, _SERVER_PRELUDE)


def render_pins_agent(contracts: Contracts) -> str:
    return _render_python(contracts, _AGENT_PRELUDE)


def _render_typescript_enum(name: str, doc: str, members: tuple[PinTerm, ...]) -> str:
    body = "".join(_wrap(m.doc, "  // ") + f"  {member_key(m.name)}: {json.dumps(m.name)},\n" for m in members)
    return (
        f"\n/** {doc} */\nexport const {name} = {{\n{body}}} as const;\n"
        f"export type {name} = (typeof {name})[keyof typeof {name}];\n"
    )


def _to_camel(name: str) -> str:
    head, *rest = name.split("_")
    return head + "".join(part.capitalize() for part in rest)


def render_pins_typescript(contracts: Contracts) -> str:
    pins = _load(contracts)
    enums = "".join(_render_typescript_enum(name, doc, getattr(pins, field)) for name, field, doc in _ENUMS)
    caps = "".join(_wrap(c.doc, "  // ") + f"  {_to_camel(c.name)}: {c.value},\n" for c in pins.caps)
    return (
        _TS_HEADER
        + "\n"
        + _wrap(pins.doc, "// ")
        + enums
        + "\n/** The caps the server holds and the dashboard shows. */\n"
        + f"export const PIN_CAPS = {{\n{caps}}} as const;\n"
    )
